def countPairsRotated(nums, target):
    n = len(nums)
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        else:
            hi = mid
    s = lo
    left, right = 0, n - 1
    count = 0
    while left < right:
        total = nums[(s + left) % n] + nums[(s + right) % n]
        if total < target:
            left += 1
        elif total > target:
            right -= 1
        else:
            count += 1
            left += 1
            right -= 1
    return count
